package app.kinnect.live;
import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Persistent Kinnect brand and navigation around account feature content. */
final class CommerceChrome {
 private static Drawable pressable(int color,int ripple,int radius,float density){GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(radius,density));GradientDrawable mask=new GradientDrawable();mask.setColor(Color.BLACK);mask.setCornerRadius(dp(radius,density));return new RippleDrawable(ColorStateList.valueOf(ripple),bg,mask);}
 static View wrap(Activity a,View content){final float density=a.getResources().getDisplayMetrics().density;boolean compact=a.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;int variant=WebTheme.isDark(a)?1:0,card=WebDesign.CARD[variant],ink=WebDesign.INK[variant],muted=WebDesign.MUTED[variant],purple=WebDesign.PURPLE[variant],line=WebDesign.LINE[variant],ripple=(purple&0x00ffffff)|0x22000000;LinearLayout root=new LinearLayout(a);root.setOrientation(1);if(android.os.Build.VERSION.SDK_INT>=29)root.setForceDarkAllowed(false);root.setBackgroundColor(WebDesign.BG[variant]);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(16,density),0,dp(12,density),0);header.setBackgroundColor(card);ImageView logo=new ImageView(a);logo.setImageResource(a.getResources().getIdentifier("kinnect_logo","drawable",a.getPackageName()));header.addView(logo,new LinearLayout.LayoutParams(dp(40,density),dp(40,density)));logo.setOnClickListener(v->go(a,"feed"));header.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));for(String[] item:new String[][]{{"bell","notifications","Thông báo"},{"store","store","Cửa hàng"},{"users-round","friends","Bạn bè"},{"message-square","inbox","Tin nhắn"},{"user-round","account","Tài khoản"}}){if(item[1].equals("account")){FrameLayout holder=new FrameLayout(a);holder.setBackground(pressable(card,ripple,99,density));ImageView face=new ImageView(a);face.setTag("commerce:account-avatar");bindAccount(a,face,density);holder.addView(face,new FrameLayout.LayoutParams(dp(24,density),dp(24,density),Gravity.CENTER));holder.setContentDescription(I18n.t(item[2]));holder.setOnClickListener(v->go(a,item[1]));header.addView(holder,new LinearLayout.LayoutParams(dp(48,density),dp(48,density)));continue;}ImageView icon=new ImageView(a);android.graphics.drawable.Drawable d=WebIcons.load(a,item[0]);d.setTint(item[1].equals("store")&&a instanceof StoreActivity?purple:ink);icon.setImageDrawable(d);icon.setBackground(pressable(card,ripple,99,density));icon.setPadding(dp(12,density),dp(12,density),dp(12,density),dp(12,density));icon.setContentDescription(I18n.t(item[2]));if(item[1].equals("store"))icon.setOnClickListener(v->{if(!(a instanceof StoreActivity))a.startActivity(new Intent(a,StoreActivity.class));});else icon.setOnClickListener(v->go(a,item[1]));header.addView(icon,new LinearLayout.LayoutParams(dp(48,density),dp(48,density)));}root.addView(header,new LinearLayout.LayoutParams(-1,dp(compact?48:WebDesign.HEADER,density)));View topLine=new View(a);topLine.setBackgroundColor(line);root.addView(topLine,new LinearLayout.LayoutParams(-1,1));root.addView(content,new LinearLayout.LayoutParams(-1,0,1));View bottomLine=new View(a);bottomLine.setBackgroundColor(line);root.addView(bottomLine,new LinearLayout.LayoutParams(-1,1));LinearLayout bottom=new LinearLayout(a);bottom.setBackgroundColor(card);bottom.setGravity(Gravity.CENTER_VERTICAL);for(String[] item:new String[][]{{"feed","house","Bảng tin"},{"discover","compass","Khám phá"},{"create","plus","Tạo"},{"shorts","clapperboard","Video"},{"live","radio","Live"}}){LinearLayout tab=new LinearLayout(a);tab.setOrientation(compact?0:1);tab.setGravity(Gravity.CENTER);tab.setBackground(pressable(card,ripple,14,density));ImageView icon=new ImageView(a);android.graphics.drawable.Drawable d=WebIcons.load(a,item[1]);d.setTint(item[0].equals("create")?Color.WHITE:muted);icon.setImageDrawable(d);if(item[0].equals("create")){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{purple,0xffff4f9a});g.setCornerRadius(dp(16,density));icon.setBackground(g);icon.setElevation(dp(4,density));icon.setPadding(dp(11,density),dp(11,density),dp(11,density),dp(11,density));tab.addView(icon,new LinearLayout.LayoutParams(dp(46,density),dp(40,density)));}else{tab.addView(icon,new LinearLayout.LayoutParams(dp(24,density),dp(24,density)));TextView name=new KinnectText(a);name.setText(I18n.t(item[2]));name.setTextSize(12);name.setTextColor(muted);name.setPadding(compact?dp(4,density):0,compact?0:dp(4,density),0,0);name.setGravity(Gravity.CENTER);name.setSingleLine(true);tab.addView(name);}tab.setContentDescription(I18n.t(item[2]));tab.setOnClickListener(v->go(a,item[0]));bottom.addView(tab,new LinearLayout.LayoutParams(0,dp(compact?48:68,density),1));}root.addView(bottom);return root;}
 private static void bindAccount(Activity a,ImageView face,float density){NativeApi.shared.call("GET","/api/me",null,(data,error,status)->{if(a.isFinishing()||a.isDestroyed()||error!=null||data==null)return;org.json.JSONObject user=data.optJSONObject("user");if(user==null)return;face.setPadding(0,0,0,0);face.setScaleType(ImageView.ScaleType.CENTER_CROP);GradientDrawable circle=new GradientDrawable();circle.setColor(WebDesign.SOFT[WebTheme.isDark(a)?1:0]);circle.setShape(GradientDrawable.OVAL);face.setBackground(circle);face.setClipToOutline(true);String path=user.optString("avatar","");if(!path.isEmpty()&&!path.equals("null"))NativeApi.shared.image(path,bytes->{if(a.isFinishing()||a.isDestroyed()||bytes==null)return;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null)face.setImageBitmap(bitmap);});else{Bitmap bitmap=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);paint.setColor(Color.WHITE);paint.setTypeface(ApprovedTypography.font(a,Typeface.BOLD));paint.setTextSize(38);paint.setTextAlign(Paint.Align.CENTER);String name=user.optString("name","K").trim();String initials=name.isEmpty()?"K":name.substring(0,1).toUpperCase(java.util.Locale.getDefault());canvas.drawText(initials,48,61,paint);face.setImageBitmap(bitmap);}});}
 private static int dp(int n,float density){return Math.round(n*density);}
 private static void go(Activity a,String target){a.startActivity(new Intent(a,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("commerce_destination",target));a.finish();}
}
